    "en": "Dioscorus I of Alexandria",
    "life": "生年不详—454年",
    "relation": "亚历山大里亚宗主教（444—451年）· 西里尔的接班人",
    "place": "alexandria",
    "bio": "西里尔的秘书和指定接班人，444年接任亚历山大里亚宗主教，不是本地埃及人。他收回被侵占的教产和船只；卡尔西顿会上有人告他把朝廷运往利比亚的小麦收购后高价倒卖。451年被革职，454年死在流放地冈格拉，科普特人奉他为圣人。",
