    "en": "Shutruk-Nakhunte",
    "life": "？—约前1155年",
    "relation": "埃兰国王（约前1184—前1155年在位）",
    "place": "susa",
    "bio": "埃兰中期最强的国王，自称“安善与苏萨之王”。他打进巴比伦尼亚，把一批古碑运回苏萨献给城神因舒希纳克；三千年后，法国考古队在苏萨卫城把这些碑挖了出来，汉谟拉比法典碑和纳拉姆-辛胜利碑如今都在卢浮宫。",
