    "en": "Narses",
    "life": "约478—约573年",
    "relation": "东罗马宦官、宫廷总管 · 平定意大利的统帅",
    "place": "ravenna",
    "bio": "亚美尼亚人，宦官出身，532年尼卡暴动时拿金子拉走蓝党。551年七十多岁时挂帅西征，带着重金雇来的伦巴第、赫鲁利、匈人大军，552年在塔吉纳打死托提拉、次年灭了最后的哥特王；此后十多年替皇帝治理意大利，查士丁二世即位后被撤职。",
