    "life": "约500—578年",
    "relation": "埃德萨主教（543—578年）· 一性论派叙利亚教会的组织者",
    "place": "edessa",
    "bio": "生在叙利亚北部，在修道院长大，约527年进京，在君士坦丁堡的修道院住了十五年，得到皇后狄奥多拉和加萨尼王哈里斯的信任。543年被祝圣为主教后乔装四处奔走，为一性论派另立了一整套主教，叙利亚正教会因此又叫“雅各派”。",
