    "bio": "罗马贵族子弟，曾任教宗驻君士坦丁堡的使节，与皇后狄奥多拉往来。537年贝利萨留废了教宗西尔维留，扶他继任。545年被押往新都，在三章案上反复多次，最终签字，回国途中死在西西里。",
