    "relation": "法兰克宫相 · 丕平二世的儿子、丕平三世的父亲",
    "place": "w_saintdenis",
    "bio": "丕平二世和情妇阿尔派达的儿子。父亲死后被继母关押，逃出来打败继母和纽斯特里亚人，718年起掌握全法兰克。他几乎年年出征，打弗里西亚人、萨克森人、巴伐利亚人、阿基坦和普罗旺斯；“马特”（铁锤）是后来编年史给的外号。",
