    "en": "Pepin the Short",
    "life": "约714—768年",
    "relation": "法兰克王（751—768年）· 查理·马特的儿子、查理曼的父亲",
    "place": "w_saintdenis",
    "bio": "查理·马特的次子，在圣但尼修道院跟修士读过书。741年和哥哥卡洛曼分任宫相，747年哥哥出家后独掌大权，751年废末代墨洛温王自立。他两次出兵意大利替教宗打伦巴第人，又从阿拉伯人手里收回纳博讷，768年死后葬在圣但尼。",
