    "en": "Charlemagne",
    "life": "748—814年",
    "relation": "法兰克王（768—814年）、伦巴第王、皇帝（800—814年）· 丕平三世的儿子",
    "place": "w_aachen",
    "bio": "丕平三世的长子。据艾因哈德，他身高是自己脚长的七倍，拉丁语说得和母语一样好，希腊语听得懂、说不好；晚年在枕头下放写字板练字，起步太晚，终究没学成。他几乎年年出征，晚年住在亚琛，常邀上百人一起泡温泉。",
