    "en": "Pope Leo III",
    "life": "生年不详—816年",
    "relation": "教宗（795—816年）· 给查理曼加冕的人",
    "place": "rome",
    "bio": "罗马本地人，不是贵族出身，前任教宗哈德良任他为圣苏珊娜堂的枢机司铎。795年哈德良下葬当天他就被选为教宗，随即把圣彼得墓的钥匙和罗马城的旗帜送给查理，表示认他做保护人。他在位二十多年，816年去世。",
