    "en": "Alcuin of York",
    "life": "约735—804年",
    "relation": "查理曼的宫廷学者 · 约克主教座堂学校出身",
    "place": "k_york",
    "bio": "诺森布里亚人，在约克主教座堂学校受教，后来主持这所学校。781年在帕尔马遇见查理曼，应邀到法兰克宫廷办学，教国王和王子们文法、修辞和天文。796年出任图尔圣马丁修道院长，在那里抄书、校订经文，804年去世。",
