    "life": "？—591年",
    "relation": "萨珊大将，米赫兰家族 · 590—591年自立为王（巴赫拉姆六世）",
    "place": "bactra",
    "bio": "安息旧族米赫兰家出身，当过雷伊的总督，绰号“楚宾”意为“标枪”，因为人又高又瘦。他在罗马战线立过功，588年大败突厥。称王失败后投奔突厥，还替可汗平过内乱，最后被库思老收买突厥王族刺杀。后来中亚的萨曼王朝自称是他的后代。",
