    "bio": "西法兰克贵族出身，在圣但尼长大，随院长进虔诚者路易的宫廷。845年起任兰斯大主教近四十年，替秃头查理出谋划策：看押戈特沙尔克，反对洛泰尔二世离婚，869年在梅斯给他加冕为洛林王。882年躲维京人逃到埃佩尔奈，死在那里。",
