    "en": "Qutayba ibn Muslim",
    "life": "669—715年",
    "relation": "倭马亚将领 · 呼罗珊总督（705—715年）",
    "place": "merv",
    "bio": "伊拉克总督哈查只提拔的将领。任呼罗珊总督十年，打下布哈拉、花剌子模和撒马尔罕，又沿锡尔河打到费尔干纳；兵不够用，就大批征募当地人从军。715年靠山哈查只和哈里发瓦利德相继去世，他起兵自保，部下不从，被自己的兵杀死。",
