    "bio": "先知的伯父艾布·塔利卜之子，自幼在先知家长大，娶先知之女法蒂玛，生哈桑、侯赛因。656年在麦地那被拥立，移都库法；隋芬对峙后接受仲裁，部下分裂，661年在库法遇刺。什叶派认他为先知指定的继承人。",
