    "en": "Mu‘awiya I",
    "life": "约600—680年",
    "relation": "倭马亚王朝开国哈里发（661—680年）· 叙利亚总督 · 奥斯曼的族人",
    "place": "ab_damascus",
    "bio": "麦加古莱什部倭马亚家族首领艾布·苏富扬之子，630年随父归顺。639年前后起任叙利亚总督二十年，靠叙利亚部落兵和原班基督徒官员坐镇，649年建起水师。奥斯曼被杀后不认阿里，661年得天下，676年立儿子叶齐德为嗣。",
