    "relation": "阿拔斯王朝第七任哈里发（813—833年）· 哈伦·拉希德之子",
    "place": "ab_baghdad",
    "bio": "哈伦·拉希德与呼罗珊巴德吉斯的波斯女奴所生，比异母弟艾敏大半岁。靠呼罗珊军打赢兄弟内战，坐镇木鹿到819年才回巴格达。他资助翻译希腊哲学和天文，信穆尔太齐赖派，833年推行“古兰经受造”的审查，同年征东罗马途中病死。",
