    "place": "an_cordoba",
    "bio": "750年阿拔斯家夺权，这位倭马亚王子逃过追杀，在北非的柏柏尔人中间躲了几年，755年渡海，次年打败总督，在科尔多瓦称埃米尔。他买柏柏尔人和奴隶组常备军，平了各地叛乱，785年起建大清真寺，788年死，儿子希沙姆一世继位。",
