    "life": "约938—1002年",
    "relation": "科尔多瓦哈里发国的宰相（978—1002年）· 实际统治者",
    "place": "an_cordoba",
    "bio": "阿尔赫西拉斯一带的阿拉伯地主之子，学法律起家，得哈里发宠妃苏卜赫信任。976年起替十岁的希沙姆二世掌权，除掉同僚和岳父，把哈里发关在宫里，号“曼苏尔”（胜利者）；成批招北非柏柏尔兵，北征五十多次，1002年死在北征归途。",
