    "life": "约前484—约前425年",
    "relation": "希腊史家 ·《历史》的作者",
    "place": "ea_halicarnassus",
    "bio": "生在小亚细亚的哈利卡纳苏斯，四处游历，写成《历史》九卷，记希波战争的来龙去脉和沿途各族的风俗。第4卷写黑海北岸的斯基泰人，是这一带最早的成段记载；他到过奥尔比亚，许多事是向当地人打听来的。",
