    "bio": "据弗雷德加，出身桑斯一带的法兰克商人。623年带商队到斯拉夫人那里做买卖，正赶上他们反阿瓦尔人，随军立功，被推为王，在位三十五年。631年在沃加斯提斯堡大败法兰克王达戈贝尔特的军队。王国的确切位置不明。",
