    "bio": "费尔南多一世的次子，1065年分得莱昂和托莱多的贡金。1072年被哥哥桑乔二世打败，流亡托莱多；同年桑乔遇刺，他回来接下全部家业，1077年起自称“全西班牙的皇帝”。1085年拿下托莱多，穆斯林史书所录他的信里自称“两教之君”；次年在萨格拉哈斯败给穆拉比特人，此后二十多年转攻为守。1108年唯一的儿子战死，次年他死在托莱多，女儿乌拉卡继位。",
