    "bio": "潘普洛纳王加西亚二世之子，1004年即位。他娶卡斯蒂利亚伯爵的女儿，她的弟弟、年轻的伯爵遇刺后，就让儿子费尔南多接管卡斯蒂利亚，又并了索夫拉韦、里瓦戈萨，1034年占莱昂城，常驻纳赫拉。他跟克吕尼通好，整修通往莱昂的路。1035年10月死，葬在奥尼亚，墓碑称他“蒙天主恩典的西班牙王”；生前把各块地分给几个儿子。",
