    "bio": "亚美尼亚人出身的将军巴德尔·贾马利之子，生在阿卡。1094年父亲死后继任维齐尔，立了老哈里发的幼子穆斯塔里，老哈里发的长子尼扎尔起兵被杀，伊斯玛仪派由此分裂。1098年从突厥人手里夺回耶路撒冷，次年耶路撒冷被十字军攻破，阿夫达勒带援军在阿斯卡隆兵败；此后年年出兵攻耶路撒冷王国。1121年12月遇刺身死。",
