    "bio": "图林根方伯手下的家臣（ministeriales）之家出身。接手时条顿骑士团还很弱，赫尔曼一边替腓特烈二世跟教宗斡旋，一边替骑士团讨特许：1211年派骑士去匈牙利守边，1225年被国王赶走；1226年拿到皇帝在里米尼颁的金玺诏书，1230年派兵进普鲁士，1237年并了利沃尼亚的宝剑骑士团。1239年死在萨勒诺。",
