    "relation": "教宗（1159—1181年）· 原名罗兰，锡耶纳人",
    "place": "bb_venice",
    "bio": "锡耶纳人，1150年被尤金三世封为枢机，1153年起任教廷首相；1156年替哈德良四世跟西西里谈成贝内文托条约，1157年作为使节到贝桑松送信。1159年被枢机多数选为教宗，红胡子另立对立教宗，亚历山大1162—1165年避居法兰西，靠伦巴第联盟和西西里撑住。1177年在威尼斯跟红胡子和解，1179年召开第三次拉特兰会议，定下三分之二多数选教宗。1181年8月死在奇维塔卡斯泰拉纳，卢修斯三世继位。",
