    "place": "bb_braunschweig",
    "bio": "韦尔夫家，骄傲者亨利与洛塔尔三世的独女格特鲁德所生。父亲的萨克森、巴伐利亚1138—1139年被康拉德三世夺走，1142年狮子亨利拿回萨克森，1156年红胡子又把巴伐利亚还给狮子亨利。狮子亨利向易北河以东扩张，建了慕尼黑、吕贝克，1168年娶英王亨利二世的女儿玛蒂尔达。1176年不肯随红胡子出兵，1180年被剥夺两个公国，1182年流亡到岳父那里；1194年跟亨利六世和解，次年死去，葬在不伦瑞克。儿子奥托四世后来当了皇帝。",
