    "bio": "路易九世之孙、腓力三世之子，外号“美男子”，因冷峻寡言被对手称作“一尊雕像”。1285年即位，重用法学家治国；为军费向教士征税、首开三级会议，1303年派人突袭阿纳尼扣押教宗卜尼法斯八世，又毁掉圣殿骑士团、并入里昂。",
