    "bio": "原为瑞士北部阿尔高与上阿尔萨斯的小伯爵。1273年被选帝侯当作面瓜选为国王以结束大空位；上台后借皇权于1278年杜恩克鲁特会战击杀波希米亚王奥托卡二世，将奥地利与施蒂里亚封给自家儿子，奠定哈布斯堡六百余年基业。晚年向教宗让步承认教宗国独立以求传位长子，遭三大主教与波希米亚联手抵制未果，1291年病逝。",
