    "place": "ge2_znojmo",
    "bio": "查理四世次子，1387年因娶匈牙利女王玛丽亚成为匈牙利国王，1396年率十字军在尼科波利斯败于奥斯曼。1410—1411年凭自家勃兰登堡选票与无嗣兄长文策尔的波希米亚继承权当选德意志王；1414—1418年主持康斯坦茨大公会议废三立一终结教会大分裂，把勃兰登堡封给霍亨索伦家族，却因背弃通行证烧死胡斯引发长达十七年的胡斯战争。1437年身着皇袍坐死于宝座，卢森堡男丁断绝，三顶王冠传归女婿哈布斯堡的阿尔布雷希特二世。",
