    "place": "colonia",
    "bio": "士瓦本劳因根人，在帕多瓦求学时入多明我会，先后在科隆、巴黎大学任神学教授，曾任雷根斯堡主教。他把亚里士多德全部著作与自然科学逐部评注介绍给拉丁世界，培养出阿奎那，生前号称“博学博士”，1280年卒于科隆。",
