    "bio": "查理七世长子，青年时两度叛父并躲进宿敌勃艮第公国避难五年，1461年父王因怕他下毒绝食饿死后继位。他厌恶骑士排场，常穿旧衣戴铅章毡帽，专靠金钱、密探与外交代理人织网算计，外号“宇宙蜘蛛”：1465年分化瓦解诸侯“公益同盟”，1470年在昂热撮合死敌玛格丽特王后与沃里克伯爵反攻英国，1475年在皮基尼用金币买退爱德华四世大军，1477年出钱借瑞士长矛兵砍死勃艮第公爵大胆查理，一举吞并勃艮第、安茹与普罗旺斯，奠定近代法兰西专制王权。",
