    "place": "uk7_london",
    "bio": "小贵族次子出身的无地骑士，早年靠比武大会击败五百名骑士扬名，被埃莉诺赎出重用，迎娶“强弓手”之女成为彭布罗克伯爵。一生忠事亨利二世、小亨利、理查一世、约翰与亨利三世五位国王，年届七旬仍披甲击败法军、重发《大宪章》，被誉为“世上最伟大的骑士”。",
