    "bio": "本名铁木真，出身蒙古乞颜部孛儿只斤氏，早年丧父历尽部族离叛，终统一漠北高原，于1206年在斡难河源头被推举为“成吉思汗”，废氏族旧制、按十进制设九十五个千户并颁布《大扎撒》。1218年因花剌子模杀害商队与使者，于1219—1225年亲率大军发动第一次西征，踏平布哈拉、撒马尔罕等中亚与波斯名城；1227年在灭西夏途中病逝于六盘山。",
