    "place": "mw_sarai",
    "bio": "成吉思汗长子术赤之子，人称“赛因汗（仁善之汗）”。1235年奉窝阔台大汗之命统帅各支宗王长子与名将速不台发动第二次西征（长子西征），1237—1240年借冬季冰封河道踏平弗拉基米尔、莫斯科与基辅，1241年分兵击溃波兰与匈牙利主力，饮马多瑙河。1242年闻窝阔台死讯回师伏尔加河下游建都萨莱，开创统治东欧与罗斯两百余年的金帐汗国。",
