    "place": "pt_samarkand",
    "bio": "出身西察合台汗国突厥化蒙古巴鲁剌思部贵族，青年时作战右腿右臂中箭致残，波斯语称“跛子帖木儿（Timur-e Lang）”。因非成吉思汗黄金家族血统，1370年定都撒马尔罕后终身只称“大埃米尔”与“古列干（驸马）”，立察合台后裔为傀儡汗。三十五年间踏平波斯（在伊斯法罕筑七万颗人头骷髅塔）、北毁金帐汗国萨莱、南洗印度德里、西破马穆鲁克，并于1402年安卡拉之战生擒奥斯曼苏丹巴耶济德一世；1404年底率二十万大军东征明成祖朱棣，1405年2月在讹答剌行营病死。",
