    "place": "po_bursa",
    "bio": "乌古斯突厥卡伊部首领埃尔图鲁尔之子，盘踞安纳托利亚西北比提尼亚边境小镇索于特；“奥斯曼（Ottoman）”之名即源于其阿拉伯文名字乌斯曼（Uthman）。罗姆苏丹国衰亡之际，奥斯曼一世利用紧贴东罗马帝国富庶防区的地利，以圣战（加齐）战利品吸引各路突厥武士与流民投奔，逐步蚕食尼西亚与布尔萨周边。1326年临终前听到儿子奥尔汗攻克大城布尔萨的捷报，死后迁葬布尔萨。",
