    "en": "Francisco Pizarro",
    "life": "约1478—1541年",
    "relation": "秘鲁的征服者 · 新卡斯蒂利亚总督",
    "place": "sp1_cajamarca",
    "bio": "生于卡斯蒂利亚的特鲁希略（Trujillo），1529年获王室特许。1532年在卡哈马卡俘获印加王阿塔瓦尔帕，次年将其处死，进占库斯科，1535年建利马。征服者随后内斗，合伙人阿尔马格罗（Almagro）1538年被皮萨罗一方处死，1541年6月26日皮萨罗在利马被阿尔马格罗一派杀死。",
