    "place": "rome",
    "bio": "本名乔瓦尼·德·美第奇，七岁领受教职、十三岁任枢机主教。1513年当选教宗后大肆挥霍，为筹措重建圣彼得大教堂巨资，与霍亨索伦的阿尔布雷希特及富格尔银行签下德意志赎罪券分销合同，直接触发1517年路德宗教改革；初期因想在1519年帝国大选中拉拢萨克森选帝侯而对路德大事化小，1520—1521年发诏绝罚路德已无法遏制新教浪潮。",
