    "en": "John Calvin",
    "life": "1509—1564年",
    "relation": "加尔文宗（改革宗）创立者 · 《基督教要义》作者、日内瓦宗教领袖",
    "place": "rf1_geneva",
    "bio": "法国皮卡第出身的人文主义法学家，改信新教流亡瑞士，1536年出版《基督教要义》，后长期主政日内瓦。他将新教推向彻底的“双重预定论”，主张善行换不来福报、得救与否早在创世前由上帝定死，信徒唯有靠信仰之跃与在世俗工作里勤勉节俭来印证选民身份，深刻塑造了荷兰、苏格兰、法国胡格诺派与英美清教徒精神。",
