    "en": "Charles V, Holy Roman Emperor",
    "life": "1500—1558年",
    "relation": "神圣罗马皇帝（1519—1556年）· 西班牙国王（卡洛斯一世，1516—1556年）· 哈布斯堡王朝",
    "place": "c5_yuste",
    "bio": "勃艮第的玛丽与马克西米利安一世之孙、胡安娜之子，一身继承西班牙及美洲、尼德兰、奥地利和那不勒斯。1519年靠富格尔家的钱当选皇帝。1525年军队在帕维亚活捉法王，1527年断饷的军队洗劫罗马，1530年受教宗加冕。一生和法国、奥斯曼、德意志新教三面作战，1555—1556年退位，把西班牙一支交给儿子腓力二世，奥地利一支和皇位交给弟弟斐迪南一世。",
