    "en": "Pope Clement VII",
    "life": "1478—1534年",
    "relation": "教宗（1523—1534年）· 本名朱利奥·德·美第奇，1478年遇刺的朱利亚诺之私生子",
    "place": "rome",
    "bio": "洛伦佐的侄子，利奥十世的堂弟，替利奥管事多年，名声很好。当选后在法国和皇帝之间来回转向，1527年罗马被洗劫，自己被关在圣天使堡。1529年和查理和解，1530年给他加冕，换来查理的兵把美第奇送回佛罗伦萨。亨利八世的离婚案他拖了六年，英国因此离开罗马。1533年把凯瑟琳嫁进法国王室，次年去世。",
