    "en": "Pope Paul III",
    "life": "1468—1549年",
    "relation": "教宗（1534—1549年）· 本名亚历山德罗·法尔内塞，天主教改革的开启者",
    "place": "rome",
    "bio": "出身罗马豪族法尔内塞，1493年由亚历山大六世封为枢机，一般认为靠的是妹妹朱莉娅。早年有情妇和子女，后来断了关系。1534年当选，批准耶稣会，督促米开朗基罗画完《最后的审判》，哥白尼的书也题献给他，同时封孙子和外孙当枢机，把帕尔马封给私生子。拖到1545年才开特兰托大公会议。",
