    "bio": "辅佐古斯塔夫二世改革瑞典内政与军制的核心重臣。1632年11月古斯塔夫二世在吕岑阵亡、国内年仅六岁的女王克里斯蒂娜继位后，奥克森谢纳临危不乱坐镇德意志，于1633年召集法兰克尼亚、士瓦本与莱茵新教诸侯组建“海尔布隆同盟”，继续指挥瑞典名将霍恩、巴纳尔与伯恩哈德在德意志节节胜利，并与华伦斯坦秘密周旋。",
