    "place": "w_paris",
    "bio": "本名阿尔芒·让·迪普莱西，二十一岁任吕松主教，1622年获封天主教枢机，1624年起任法王路易十三首席大臣。在国内铁腕镇压胡格诺派武装特权与大贵族叛乱、加强王权集权；在外交上奉行“国家利益高于宗教教派”，为打破西班牙与奥地利两家哈布斯堡对法国的合围，先出钱资助新教丹麦与瑞典攻打帝国，1634年瑞典在讷德林根惨败后更于1635年5月亲自率法国下场向哈布斯堡宣战，为法兰西取代西班牙与德意志成为欧洲霸主奠定胜局。",
