    "bio": "法兰克史书里头一个面目清楚的丹麦王。查理曼打完萨克森，古德弗雷德成了法兰克的直接邻居。808年古德弗雷德毁掉法兰克盟友的商埠雷里克，把商人迁到海泽比收税，并加修丹麦墙；810年派两百条船掠弗里西亚，同年被自己人杀死。他同时动用了军队、关税和工事，说明维京时代开始时丹麦已有相当的王权。",
