    "bio": "红发埃里克之子，可能生于冰岛。两部萨迦对他的记载并不一致：《红发埃里克萨迦》说他从挪威回格陵兰时被风吹到文兰；《格陵兰人萨迦》说别人先看到这片陆地，莱夫后来专程前往。两书多被看作文学作品，史实程度有争议。兰塞奥兹牧草地证实北欧人到过北美，但不能证明那就是莱夫的营地。",
