    "en": "Duke of Lerma",
    "life": "1552/1553—1625年",
    "relation": "腓力三世的宠臣（1598—1618年）· 枢机主教",
    "place": "sp3_valencia",
    "bio": "原是德尼亚侯爵，1595年任巴伦西亚总督，后成为腓力三世的宠臣，垄断通往国王的渠道。任内停战、驱逐摩里斯科人，也因个人敛财和家族专权招致众怒。1618年被儿子乌塞达公爵（Duke of Uceda）与对手联手赶下台，靠枢机主教身份自保。传统评价甚低，也有史家认为其和平路线比前后两朝都更合财力。",
