    "bio": "十五岁嫁给大她三十九岁的诺曼底大总管布雷泽，1531年守寡后只穿黑白两色。亨利二世继位后替他看顾王室子女，分派官职，1548年封瓦朗蒂努瓦公爵夫人。亨利死后被逐出宫廷，退居阿内。2008年学者检验她的遗骨，金含量是常人的二百五十倍，推测她长年喝含金的药水。",
