    "place": "fsb_fig_vincennes",
    "bio": "亨利二世和凯瑟琳·德·美第奇的第三子，十岁继位，加冕时哭了。十三岁在鲁昂宣布亲政，实权仍在母亲手里，爱打猎，写过一本打猎的书，生前没有出版。1570年娶皇帝马克西米利安二世的女儿伊丽莎白（Elisabeth of Austria），只有一个女儿；情妇玛丽·图歇（Marie Touchet）生的儿子成了后来的昂古莱姆公爵。1574年5月30日死，王位归弟弟亨利。",
