    "place": "fma_pitti",
    "bio": "托斯卡纳大公弗朗切斯科一世之女，母亲是哈布斯堡家的女大公。不满三岁丧母，十二岁丧父，由叔父斐迪南一世抚养。1600年嫁亨利四世，九年生六个孩子；女儿们分别成了西班牙、萨伏依、英格兰的王后或公爵夫人。1610年起摄政，1617年被儿子赶到布卢瓦，1619年出逃起兵，1622年回到御前会议，1630年愚人日败给自己提拔的黎塞留，1631年流亡，1642年死在科隆。",
