    "bio": "生在佛罗伦萨，比萨大学读过书，1600年随玛丽来法国，次年娶她的侍女加利盖。亨利四世死后连升：参事、第一宫廷侍从、皮卡第副总督、元帅。法语夹着意大利语，举止张扬，为全国所恨。1617年4月24日被路易十三的卫队打死，财产归了吕伊内。",
