    "bio": "财政总监埃菲亚元帅的儿子，1632年父亲死后由黎塞留照看。1639年入宫，受路易十三宠信，宫里叫他“大人”（Monsieur le Grand）。国王管得紧，他受不了，私下嘲笑国王，在外花天酒地。1641年卷入苏瓦松伯爵之乱未被发现，1642年与加斯东同西班牙订约，败露后和朋友德图同日在里昂被斩，年仅二十二岁。维尼（Alfred de Vigny）的小说和古诺（Charles Gounod）的歌剧都写过他。",
