    "en": "Girolamo Savonarola",
    "life": "1452—1498年",
    "relation": "佛罗伦萨圣马可修道院院长 · 多明我会传道修士 · 1494—1498年主导佛罗伦萨",
    "place": "ir_florence",
    "bio": "费拉拉人，1490年应洛伦佐·德·美第奇之邀回佛罗伦萨，讲道骂富人和腐败的教会，约1493年起预言“新居鲁士”翻山而来。1494年法军到来，预言应验，他带团见查理八世，此后不担任何官职，靠讲坛和修士党主导新共和国。1497年被亚历山大六世绝罚，1498年4月7日过火神判泡汤，被捕受刑，5月23日与两名修士在领主广场被吊死焚尸。路德后来读过他的著作。",
