    "en": "Louis XII of France",
    "life": "1462—1515年",
    "relation": "法兰西国王（1498—1515年）· 奥尔良公爵出身，瓦卢瓦—奥尔良支系唯一的国王",
    "place": "iw1_blois",
    "bio": "少年被路易十一逼娶残疾的公主让娜。1485年起兵争摄政，1488年圣奥班兵败被俘，关了约三年。1498年以旁支继位，离婚后娶查理八世的遗孀布列塔尼的安妮。1499年夺米兰，1501年与费迪南二世瓜分那不勒斯，1504年被西班牙赶走。因减轻军役税、司法改革，被称为“人民之父”。1512年丢米兰，1515年元旦去世，无子，传给女婿弗朗索瓦一世。",
