    "place": "naples",
    "bio": "在格拉纳达战争中成名，1495年带兵到意大利，帮那不勒斯赶走查理八世留下的法军。1503年在切里尼奥拉和加里利亚诺河两败法军，把那不勒斯拿下。他把长矛、火绳枪和剑编在同一支步兵里，是后来西班牙方阵的前身。费迪南二世怕他功高，1507年把他调回，不再重用。",
