    "en": "Perkin Warbeck",
    "life": "约1474—1499年",
    "relation": "图尔奈布商之子 · 冒充伦敦塔失踪的约克公爵理查 · 亨利七世最大外部心腹大患",
    "place": "bh7_tyburn_fig",
    "bio": "原名皮埃尔雄·德·韦尔贝克，佛兰德图尔奈城收税官之子。1491年在爱尔兰被约克余党包装为理查三世手下逃生的爱德华四世次子理查，先后获法王查理八世、神圣罗马皇帝马克西米利安一世、勃艮第公爵遗孀玛格丽特及苏格兰王詹姆士四世承认资助，三次登陆英格兰均告失败，1497年被俘，1499年11月在伦敦泰伯恩被绞死。",
