    "en": "Thomas Cranmer",
    "life": "1489—1556年",
    "relation": "坎特伯雷大主教（1533—1555年）· 英国国教《公祷书》主编 · 亨利八世与爱德华六世改教教父",
    "place": "bh8c_oxford_fig",
    "bio": "剑桥大学神学学者，因献策“绕开教宗、直接征询全欧大学神学家意见判亨利八世婚姻无效”获博林家族举荐，1533年出任坎特伯雷大主教，先后替亨利八世宣判凯瑟琳、安妮·博林与克利夫斯的安妮三段婚姻无效。在爱德华六世朝主持编写塑造英语散文传统的1549与1552年版《公祷书》；玛丽一世复辟天主教后被捕入狱，一度软弱签下六份悔过书，1556年3月在牛津临刑前当众翻供，主动将签过悔过书的右手先伸进烈火烧毁。",
