    "bio": "西班牙国王腓力三世的长女，1615年十四岁嫁给路易十三，此后两国长年交战，她在法国宫廷一直受猜忌。婚后二十三年才生下路易十四。1643年丈夫死后，她请高等法院作废遗嘱里限制她的条款，全权摄政，重用马萨林；投石党年间几度带儿子离开巴黎，始终不肯放弃马萨林。1651年儿子成年后仍坐镇御前会议，1661年马萨林死后退居，常住她修建的圣宠谷修道院，1666年1月20日死于乳腺癌。她和马萨林是否秘密结婚，史家至今争论。",
