    "bio": "孔代亲王亨利二世之子，原称昂吉安公爵，1641年奉父命娶黎塞留的外甥女。1643年二十一岁时在罗克鲁瓦打败西班牙方阵，此后在弗赖堡、讷德林根、敦刻尔克、朗斯屡胜，1646年底袭爵孔代亲王。投石党时先替朝廷围巴黎，1650年被马萨林关押一年，1651年起兵，1652年投西班牙，替西班牙打了七年仗。比利牛斯和约后获赦，1674年在塞内夫与奥兰治的威廉苦战，晚年住在尚蒂伊，1686年死于枫丹白露。",
