    "bio": "色当的布永公爵之子，母亲是荷兰奥兰治亲王“沉默者”威廉的女儿，自幼信新教，少年时到舅舅们统率的荷兰军中学打仗。三十年战争中与昂吉安公爵并肩作战，1643年封元帅，1648年与瑞典军在楚斯马斯豪森打垮帝国军。投石党时先站在亲王一边，1651年改投国王，1652年在布莱诺、圣安托万城郊挡住孔代，1658年打赢沙丘之战，1660年封王国军队总元帅。1668年改信天主教，1675年7月27日在萨斯巴赫中炮阵亡，路易十四准他葬入王陵圣但尼。",
