    "bio": "腓力四世与法国公主伊丽莎白（路易十三的妹妹）的长女，1638年生在埃斯科里亚尔，和路易十四同年生，两人是双重表亲。1659年按比利牛斯和约许嫁路易十四，放弃西班牙继承权，条件是付清五十万金埃居嫁妆。1660年6月3日在富恩特拉维亚由人代行婚礼，9日在圣让-德吕兹正式成婚。她常在婆婆安妮那里讲西班牙语、喝热巧克力，对政事过问不多；1672年国王出征荷兰时曾短期摄政。生了三子三女，只有王太子路易长大成人。1683年7月30日死于凡尔赛。",
