    "bio": "巴黎穿袍贵族之子，家徽是一只松鼠。投石党时站在马萨林一边，1653年起任财政总监，靠自己的信用替国家借钱，也借机敛财，买下贝勒岛修筑要塞，1657—1661年修沃子爵城堡，供养莫里哀、拉封丹等文人。1661年9月5日在南特被捕，特别法庭审了三年，判逐出国境，国王改为终身监禁，1680年3月23日死于皮内罗洛。后来有人说他就是“铁面人”，史家多不采信。",
