    "bio": "兰斯商人家庭出身，二十一岁时父亲替他买了军需专员的官，后来做陆军国务秘书勒泰利耶的秘书，1651年起替马萨林管私产。1659年写备忘录揭富凯的账，1661年参与筹划抓捕富凯，此后二十多年掌管财政、建筑、工场、商业和海军：设特别法庭追查金融家，提高关税保护本国工场，创办铭文学院、科学院和巴黎天文台，支持开凿米迪运河。为人冷峻，塞维涅夫人给他起外号叫“北方”（Le Nord）。1683年9月6日死于巴黎。",
