    "en": "André-Hercule de Fleury",
    "life": "1653—1743年",
    "relation": "路易十五的老师 · 首席大臣（1726—1743年，未受名号）· 枢机（1726年起）",
    "place": "fl15_issy_fig",
    "bio": "朗格多克洛代沃人，父亲是包税人。做过王后玛丽-泰蕾兹和路易十四的施赈司铎，1698年任弗雷瑞斯主教，1715年5月被路易十四指定为曾孙的老师。1726年赶走波旁公爵后执政十七年，生活节俭，用财政总监奥里理财，稳住币值、按时付国债利息，修路靠征发农民徭役。对外和英国首相沃波尔一样求和，波兰王位继承战争换来了洛林；奥地利王位继承战争开打时，他已压不住宫里的主战派。1743年1月死在伊西，年近九十。",
