    "place": "fl15_marbre_fig",
    "bio": "勃艮第公爵和萨伏伊的玛丽-阿德莱德之子，两岁时父母和哥哥相继死于麻疹，五岁继位，由摄政王奥尔良公爵代政。1725年娶波兰公主玛丽·莱什琴斯卡。前半生把国家交给老师弗勒里，1743年起亲政，1744年在梅斯病愈后被称为“被爱的人”。此后打完两场大仗，丢了加拿大和印度，又和高等法院、教士反复拉锯，名声一落千丈。在位近五十九年，1774年死于天花，是唯一生死都在凡尔赛的法国国王。",
