    "en": "Charles-Louis de Secondat, Baron de Montesquieu",
    "life": "1689—1755年",
    "relation": "波尔多高等法院庭长（1716—1726年）· 《论法的精神》作者 · 法兰西学院院士",
    "place": "fen_labrede_fig",
    "bio": "生在波尔多以南的拉布雷德城堡，学法律，1714年任波尔多高等法院推事，1716年继承伯父的庭长职位和孟德斯鸠男爵的名号。1721年匿名出版《波斯人信札》成名，1726年卖掉庭长的终身任期，1728年当选法兰西学院院士，随后游历欧洲三年，在英国住了一年半。1748年出版《论法的精神》，主张权力互相制约，美国宪法和法国1791年宪法都受它影响。1751年此书被列入罗马的禁书目录。1755年2月10日死在巴黎。",
