    "bio": "日内瓦钟表匠之子，十五岁离开日内瓦，在萨伏依改信天主教，1742年到巴黎，和狄德罗结交，替《百科全书》写音乐条目。1750年以第戎学院的征文成名，1752年歌剧《乡村占卜者》在宫廷演出，1754年回日内瓦恢复新教信仰和公民身份。1762年《社会契约论》《爱弥儿》出版后被巴黎和日内瓦通缉，此后多年流亡瑞士和英国。晚年写《忏悔录》，1778年7月2日死在埃默农维尔，1794年迁葬先贤祠。",
