    "place": "fsy_sanssouci_fig",
    "bio": "普鲁士国王腓特烈·威廉一世之子，少年时和好友卡特密谋出逃，被父亲抓回，卡特被处死。1740年即位，当年就出兵夺取奥地利的西里西亚。七年战争中同时对付奥地利、法国、俄国和瑞典，几乎亡国，1762年1月俄国女皇伊丽莎白死后，新沙皇彼得三世倒向普鲁士，局面才翻转。吹长笛、作曲，用法文写作，1747年在波茨坦接见过巴赫。1772年参与第一次瓜分波兰。1786年8月17日去世，后世称“大帝”。",
