    "en": "William Pitt the Elder, 1st Earl of Chatham",
    "life": "1708—1778年",
    "relation": "英国下院议员（1735—1766年）· 南方事务大臣（1756—1761年）· 查塔姆伯爵",
    "place": "fsy_commons_fig",
    "bio": "马德拉斯总督“钻石皮特”的孙子，当过骑兵少尉。1735年进下院，以抨击沃波尔、反对给汉诺威付补贴出名，长期不肯受封爵位，人称“伟大的平民”。1746年任军队出纳，不收前任惯拿的利息和回扣。七年战争中主持英国战事，1761年10月下台。1766—1768年再度主持内阁，受封查塔姆伯爵；晚年在上院替北美殖民地说话，1778年5月11日去世。他的儿子小皮特后来也当了首相。",
