    "en": "Étienne-François, Duke of Choiseul",
    "life": "1719—1785年",
    "relation": "路易十五的外交大臣、陆海军大臣（1758—1770年）· 蓬帕杜尔夫人的盟友",
    "place": "fsy_chanteloup_fig",
    "bio": "1719年生在洛林的南锡，原是洛林公爵的臣民。靠蓬帕杜尔夫人的提携出任驻罗马、驻维也纳大使，1758年底起主持外交，后来兼管陆军和海军，签了同西班牙的家族协定和巴黎和约。战后改革军队、重建海军，接手科西嘉，促成王太子和奥地利公主玛丽-安托瓦内特的婚事。1770年12月24日被杜巴丽夫人一派扳倒，流放到尚特卢庄园，1785年死在巴黎。",
