    "bio": "王太子路易和萨克森公主玛丽-约瑟芬之子，生在凡尔赛，1765年父亲病死后成为王太子，1770年娶奥地利公主玛丽-安托瓦内特，1774年即位。在位初年召回高等法院，先后起用杜尔哥、内克尔等人改革，出兵援助美国独立。1789年召开三级会议，1791年出逃未成，1792年王政被废，1793年1月21日被送上断头台。",
