    "bio": "生于日内瓦，父亲是从勃兰登堡迁来的法学教授。十六岁进银行当学徒，后来在巴黎与人合伙开银行，七年战争末年做英国债券和粮食生意发了家。1764年娶牧师的女儿苏珊·屈尔绍（Suzanne Curchod），1766年生下女儿热尔梅娜，就是后来的斯塔尔夫人。1776—1781年主持财政，借钱打美国独立战争，公开王室账目后辞职；1788年8月被召回，促成第三等级代表加倍；1789年7月11日被罢免，巴黎随即起事，16日又被召回；1790年9月辞职，回到日内瓦湖边的科佩。",
