    "bio": "生于波士顿，少年时在哥哥的印刷所当学徒，后来在费城办报，出版《穷理查年鉴》。他用风筝做雷电实验，发明避雷针，成了欧洲知名的科学家。1776年他在独立宣言上签名，同年作为大陆会议的代表出使法国，在帕西一住八年，争取到法国的秘密援助、贷款和同盟，1783年参与签订承认美国独立的巴黎和约。1785年回到费城，1787年参加制宪会议，1790年去世。",
