    "bio": "生于杜埃的法官世家，先后在阿图瓦和弗兰德斯做检察官，1766年起任梅斯督办官，1778年调任里尔督办官。1783年11月出任财政总监，靠借款维持信用，前后借了六亿多里弗尔。1786年他提出人人都交的土地税，1787年召开显贵会议推行，失败后被罢免，巴黎人叫他“赤字先生”。他不久去了英国，在那里和内克尔打笔仗，大革命期间替流亡的国王弟弟们出谋划策。1802年获准回国，一个月后去世。",
