    "place": "fbk_chartres_fig",
    "bio": "生于普罗旺斯的弗雷瑞斯，父亲是当地的驿站长兼王家税吏。他在巴黎圣叙尔皮斯神学院读书，1774年当神父，1783年起任沙特尔主教代理。1788年写《论特权》，1789年1月出版《第三等级是什么》，5月当选巴黎第三等级代表，6月提出成立国民议会的动议。1793年在国民公会投票处死路易十六，恐怖时期一言不发。1799年和波拿巴合谋发动雾月政变，当过临时执政，帝国时封伯爵；复辟后流亡布鲁塞尔，1836年死在巴黎。",
