    "place": "bvi_fig_broadlands",
    "bio": "爱尔兰贵族第三代帕麦斯顿子爵，早年任托利党陆军财务大臣二十年，1830年转投辉格党后长期执掌英国外交。他奉行强硬的“自由贸易炮舰外交”，1840年发动第一次鸦片战争逼清廷割让香港、开放五口通商，1850年在唐·帕西菲科事件中派舰队封锁雅典并在下院发表“罗马公民”演说。1855年克里米亚战争陷入僵局时出任首相，率英法联军攻克塞瓦斯托波尔，继而又发动第二次鸦片战争并镇压1857年印度大兵变；在内政上他长期压制议会扩权，直至1865年八十岁高龄死于任上。",
