    "en": "Toussaint Louverture",
    "life": "约1743—1803年",
    "relation": "海地革命领袖 · 圣多明各终身总督（1801—1802年）· 共和国陆军师将",
    "place": "fco_joux_fig",
    "bio": "约1743年生于圣多明各北部的布雷达种植园，父母是从西非贩来的黑奴。他早年获释，识字信天主教，自己也置过咖啡园。1791年黑奴起事后投身军伍，先联西班牙打法国，1794年国民公会废除奴隶制后转归法国共和国，升任师将，先后打退英军、统一全岛，1801年颁布自治宪法自任终身总督。1802年勒克莱尔远征圣多明各，他抵抗三个月后讲和，6月被法军诱捕押往法国，关进汝拉山的茹堡，1803年4月7日死于狱中。",
