    "place": "osm2_fig_visegrad",
    "bio": "原名巴伊察·索科洛维奇，生于波斯尼亚德里纳河畔塞尔维亚东正教农家，少年时被血税（Devshirme）征入埃迪尔内宫廷学校，历任海军总督、鲁米利亚总督，并迎娶皇太孙女伊丝米罕。1565年获苏莱曼一世提拔为大维齐尔，次年在锡盖特堡秘不发丧四十八天平稳交接皇位，在塞利姆二世与穆拉德三世朝独揽朝纲十四年：1571年夺取塞浦路斯，勒班陀海战惨败后五个多月重建舰队迫使威尼斯求和，并曾主持开凿伏尔加—顿河运河工程、恢复塞尔维亚佩奇东正教牧首区（由其亲族出任牧首）。1579年10月在府中接见请愿者时遇刺身亡。",
