    "place": "osm2_fig_isfahan",
    "bio": "生于赫拉特，萨法维沙阿穆罕默德·科达班达第三子。1588年十七岁借政变即位时，波斯正遭奥斯曼与乌兹别克东西夹击、国内土库曼红头军部落各自拥兵。阿巴斯一世先于1590年割地同奥斯曼讲和，腾出手照搬奥斯曼常备军制度：大举起用格鲁吉亚、亚美尼亚与切尔克斯改宗奴隶兵（古拉姆），组建直属沙阿的火绳枪步兵与炮兵，削夺红头军部落兵权；1598年将都城迁往伊斯法罕，并把亚美尼亚丝商迁至南郊新朱尔法垄断生丝出口以充军费。随后反攻收复大不里士、埃里温、霍尔木兹与巴格达（1623年），把萨法维波斯推上全盛；晚年多疑，杀害或弄瞎亲生诸子，1629年病逝。",
