    "place": "rus5_fig_kievopera",
    "bio": "1862年生于德累斯顿的俄国贵族家庭，在圣彼得堡大学学农学，老师里有化学家门捷列夫。1889—1902年任科夫诺省贵族首领，1903年2月任萨拉托夫省长，那是全国最穷、最不安分的省份之一，1905年革命中以强硬手段维持秩序出名。1906年任内政大臣，7月兼大臣会议主席：一面设战地军事法庭，八个月判死1102人、实际处决683人，杜马议员罗季切夫把绞索叫作“斯托雷平的领带”；一面以1906年11月9日法令准许农民退出村社、把份地变成私产。1906年8月阿普捷卡尔岛别墅被社会革命党最高纲领派炸毁，1911年9月1日在基辅歌剧院被兼当保安处线人的博格罗夫枪击，四天后去世。",
