    "bio": "原名弗拉基米尔·乌里扬诺夫，1870年生于伏尔加河畔的辛比尔斯克，父亲伊利亚·乌里扬诺夫是辛比尔斯克省的国民学校总监，靠官阶得了世袭贵族身份。1887年哥哥亚历山大因谋刺亚历山大三世被处死，同年列宁因参加反政府学潮被喀山大学开除。1903年党内分裂后领导布尔什维克派。一战期间流亡瑞士，1916年迁居苏黎世；1917年4月坐德国放行的车厢回国，发表《四月提纲》，10月夺取政权，任人民委员会主席。1918年3月力主签订布列斯特和约，8月30日遭前社会革命党人卡普兰枪击受伤。1921年推行新经济政策；1922年起多次中风，临终前建议撤掉斯大林的总书记职务，1924年1月去世。",
