      "when": "1555—1558年",
      "event": "为防法国王储妃玛丽夺位，力保小姨子伊丽莎白",
      "note": "腓力二世看清妻子玛丽一世无嗣，一旦除掉伊丽莎白就会让英格兰落入法国之手，故全力保住伊丽莎白。",
