      "event": "出任坎特伯雷大主教，颁《三条信纲》铁腕按住清教徒",
      "note": "惠特吉夫特受命整顿教会纪律，强令全体牧师签字承认《公祷书》全无错误，停职数百名清教徒牧师并破获地下印刷网。",
      "place": "bef_lambeth"
