      "event": "在葛底斯堡公墓落成礼发表两分钟、272词的传世演说",
      "note": "当天主讲人爱德华·埃弗里特一口气讲了两个小时，林肯随后起身只念了两分钟十句话；次日埃弗里特致信林肯说：“我讲两小时想逼近的核心，不如您两分钟讲得透彻。”",
      "place": "amcw_fig_gettysburg"
