      "event": "冒称彼得三世率哥萨克与农奴起义，攻破喀山，兵败押赴莫斯科斩首",
      "note": "借农奴盼望解放的心理号召吊死地主，震动半壁帝国，兵败被装入铁笼押送莫斯科处决。",
